<?php
namespace Tests\Feature\Documents;
use App\Domain\Documents\Services\RegisterDocument;use App\Models\{District,DocumentCategory,DocumentType,RevenueCircle,State,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class RegisterDocumentTest extends TestCase{use RefreshDatabase;public function test_registration_allocates_permanent_reference_and_barcode():void{$this->seed();$u=User::factory()->create();$state=State::where('code','AS')->firstOrFail();$district=District::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'state_id'=>$state->id,'code'=>'TST','name_en'=>'Test District','is_active'=>true]);$circle=RevenueCircle::create(['ulid'=>(string)\Illuminate\Support\Str::ulid(),'district_id'=>$district->id,'code'=>'C1','name_en'=>'Test Circle','is_active'=>true]);$category=DocumentCategory::firstOrCreate(['code'=>'LAND_RECORD'],['name_en'=>'Land Record']);$type=DocumentType::firstOrCreate(['code'=>'JAMABANDI'],['document_category_id'=>$category->id,'name_en'=>'Jamabandi']);$doc=app(RegisterDocument::class)->execute(['document_category_id'=>$category->id,'document_type_id'=>$type->id,'state_id'=>$state->id,'district_id'=>$district->id,'revenue_circle_id'=>$circle->id,'title'=>'Test Jamabandi','patta_no'=>'47','dag_no'=>'158','record_year'=>1968],$u->id);$this->assertMatchesRegularExpression('/^AS-LR-\d{4}-\d{10}$/',$doc->reference_no);$this->assertMatchesRegularExpression('/^LR\d{13}$/',$doc->barcode->barcode_value);$this->assertSame('AWAITING_UPLOAD',$doc->status->value);}}
